import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:test_project/ResourcesFile.dart/alertSound.dart';
import 'package:test_project/screens/dashboard.dart';
import 'package:test_project/models/alert.dart';
import 'package:test_project/providers/alert_provider.dart';
import 'package:test_project/providers/connection_provider.dart';
import 'package:test_project/providers/settings_provider.dart';
import 'package:test_project/ResourcesFile.dart/app_colors.dart';
import 'package:test_project/ResourcesFile.dart/app_images.dart';
import 'package:test_project/ResourcesFile.dart/app_strings.dart';
import 'package:tray_manager/tray_manager.dart';
import 'package:window_manager/window_manager.dart';

class MyHomePage extends StatefulWidget {
  const MyHomePage({super.key, required this.title});
  final String title;
  @override
  State<MyHomePage> createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage>
    with WindowListener, TrayListener {
  bool _isInitialized = false;
  late ConnectionProvider connectionProvider;
  late AlertProvider alertProvider;

  @override
  void initState() {
    super.initState();
    _forceHideWindowImmediately();
    _initTray();
    windowManager.addListener(this);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _initializeApp(); // ✔ Safe to call provider.initialize() here
    });
  }

  Future<void> _forceHideWindowImmediately() async {
    try {
      await windowManager.waitUntilReadyToShow();
      await windowManager.hide();
      debugPrint("Main window hidden instantly before build()");
    } catch (e) {
      debugPrint("Failed initial hide: $e");
    }
  }

  Future<void> _hideMainWindow() async {
    try {
      await windowManager.hide();
      debugPrint('Main window hidden - running in system tray mode');
    } catch (e) {
      debugPrint('Failed to hide main window: $e');
    }
  }

  Future<void> _initializeApp() async {
    try {
      debugPrint('Initializing Alert Application...');

      final settingsProvider = context.read<SettingsProvider>();
      connectionProvider = context.read<ConnectionProvider>();
      alertProvider = context.read<AlertProvider>();

      connectionProvider.setAlertCallback((alert) {
        if (alert.camName.isEmpty || alert.key.isEmpty) {
          debugPrint('Invalid alert received. Missing camName or key.');
          return;
        }

        debugPrint(' Incoming alert: ${alert.key} for ${alert.camName}');

        if (alertProvider.isCameraSilenced(alert.camName)) {
          debugPrint('🔕 Alert silenced for camera: ${alert.camName}');
          return;
        }

        final wasAdded = alertProvider.addAlert(alert);

        if (!wasAdded) {
          AlertSound.playAlertSound();
          debugPrint('⚠️ Duplicate alert ignored: ${alert.key}');
          return;
        }

        _handleNewAlert(alert);

        debugPrint('🟢 Alert processed successfully: ${alert.key}');
      });

      // Initialize API connection
      await connectionProvider.initialize(
        settingsProvider.graphQLApiRequestUrl,
        settingsProvider.userName,
      );

      await _hideMainWindow();

      setState(() {
        _isInitialized = true;
      });

      debugPrint('Application initialized successfully');
    } catch (e) {
      debugPrint('Failed to initialize application: $e');
    }
  }

  Future<void> _handleNewAlert(Alert alert) async {
    final alertProvider = context.read<AlertProvider>();

    try {
      debugPrint('Showing window for new alert: ${alert.key}');

      // Select the new alert automatically
      if (alertProvider.currentAlerts.length == 1) {
        alertProvider.selectAlert(alert);
      }

      // Show the window from system tray
      await windowManager.show();
      await windowManager.focus();

      debugPrint('Alert window displayed for: ${alert.key}');
    } catch (e) {
      debugPrint('Failed to show alert window: $e');
    }
  }

  @override
  void onWindowClose() async {
    windowManager.hide();
  }

  @override
  void onTrayIconMouseDown() {
    // _showWindow();
  }

  Future<void> _initTray() async {
    trayManager.addListener(this);
    await trayManager.setIcon(AppImages.iconApp);
    await trayManager.setToolTip(AppStrings.appName);

    await trayManager.setContextMenu(
      Menu(
        items: [
          MenuItem(
            label: "Clear all alerts",
            onClick: (menuItem) => _clearAllalerts(),
          ),
          MenuItem(
            label: "add_Dummy_alert",
            onClick: (menuItem) => _addDummyAlert(),
          ),
          MenuItem(label: AppStrings.exit, onClick: (menuItem) => _exitApp()),
        ],
      ),
    );
  }

  void _clearAllalerts() {
    debugPrint("clear all function called");
    alertProvider.clearAlerts();
  }

  void _handleAlertReceived(Alert alert) {
    final isCameraSilence = alertProvider.isCameraSilenced(alert.camName);
    print("isCameraSilence: $isCameraSilence");
    if (!isCameraSilence) {
      final wasAdded = alertProvider.addAlert(alert);
      if (wasAdded) {
        AlertSound.playAlertSound();
        debugPrint('sound has played');
        _handleNewAlert(alert);
      }
    } else {
      print("Alert not added beacause it is silenced");
      print(alertProvider.getSilenceAlertList);
    }
  }

  Alert generateDummyAlert() {
    return Alert(
      camName: "CAM026",
      alertType: "落物",
      roadName: "kalndi Road",
      detectionDatetime: DateTime.now().toIso8601String(),
      image:
          "",
    );
  }

  void _addDummyAlert() {
    final alert = generateDummyAlert();

    _handleAlertReceived(alert);
    windowManager.show(); // Restore window
    windowManager.focus();
  }

  void _exitApp() async {
    final result = await alertProvider.onWillPop();
    if (result) {
      debugPrint("Terminating the app");
      trayManager.destroy();
      windowManager.destroy();
    }
  }

  @override
  void onTrayIconRightMouseDown() {
    trayManager.popUpContextMenu();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Consumer<AlertProvider>(
        builder: (context, alertProvider, _) {
          // If there are alerts, show the dashboard with top notification bar
          if (alertProvider.currentAlerts.isNotEmpty) {
            return Column(children: [Expanded(child: DashboardNotification())]);
          }
          // When no alerts, show empty container (window is hidden anyway)
          return Container(
            color: AppColors.backgroundColor,
            child: Center(
              child: Text(
                _isInitialized
                    ? 'No alerts - Running in background'
                    : 'Initializing...',
                style: TextStyle(color: AppColors.labelTextColor, fontSize: 16),
              ),
            ),
          );
        },
      ),
    );
  }
}
